#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#define CUSTOM_STACK_SIZE (2 * 1024 * 1024) // 2 MB

void *thread_func(void *arg) {
    printf("Thread %ld: Running with custom stack\n", (long)arg);
    return NULL;
}

int main() {
    pthread_attr_t attr;
    pthread_t thread_id;
    void *stack_addr = NULL;
    size_t stack_size;
    int ret;
    int page_size = sysconf(_SC_PAGESIZE);

    // 1. Initialize attributes object
    if ((ret = pthread_attr_init(&attr)) != 0) {
        fprintf(stderr, "Error initializing attributes: %d\n", ret);
        return 1;
    }

    // 2. Allocate stack memory with proper alignment (page-aligned)
    if ((ret = posix_memalign(&stack_addr, page_size, CUSTOM_STACK_SIZE)) != 0) {
        fprintf(stderr, "posix_memalign failed: %d\n", ret);
        pthread_attr_destroy(&attr);
        return 1;
    }

    printf("Allocated stack at %p with size %zu bytes\n", stack_addr, (size_t)CUSTOM_STACK_SIZE);

    // 3. Set the custom stack address and size (MODERN APPROACH)
    if ((ret = pthread_attr_setstack(&attr, stack_addr, CUSTOM_STACK_SIZE)) != 0) {
        fprintf(stderr, "Error setting stack: %d\n", ret);
        free(stack_addr);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 4. Verify the settings using getstack
    void *retrieved_addr = NULL;
    size_t retrieved_size = 0;
    if ((ret = pthread_attr_getstack(&attr, &retrieved_addr, &retrieved_size)) != 0) {
        fprintf(stderr, "Error getting stack: %d\n", ret);
        free(stack_addr);
        pthread_attr_destroy(&attr);
        return 1;
    }

    printf("Retrieved stack: address=%p, size=%zu bytes\n", retrieved_addr, retrieved_size);
    printf("Verification: %s\n", 
           (retrieved_addr == stack_addr && retrieved_size == CUSTOM_STACK_SIZE) ? 
           "SUCCESS" : "MISMATCH");

    // 5. Create thread with custom stack
    if ((ret = pthread_create(&thread_id, &attr, thread_func, (void*)1)) != 0) {
        fprintf(stderr, "Error creating thread: %d\n", ret);
        free(stack_addr);
        pthread_attr_destroy(&attr);
        return 1;
    }

    // 6. Wait for thread to finish
    pthread_join(thread_id, NULL);

    // 7. Clean up
    pthread_attr_destroy(&attr);
    free(stack_addr);

    printf("Main: Thread completed and resources released\n");
    return 0;
}
